where w.status = 'ACTIVE'
  and w.workspace_id not like 'wrk!_exp!_%' escape '!'
  and (
    exists (
        select 1 from personal_workspaces pw
        where pw.runtime_workspace_id = w.workspace_id
          and pw.user_id = #{userId}
          and pw.status = 'ACTIVE'
    )
    or exists (
        select 1 from sessions s
        where s.workspace_id = w.workspace_id
          and s.status = 'ACTIVE'
          and s.source_type != 'SIDE_QUESTION'
          and (
            s.created_by_user_id = #{userId}
            or exists (
                select 1 from runs r
                where r.session_id = s.session_id
                  and r.triggered_by_user_id = #{userId}
            )
            or exists (
                select 1 from session_messages sm
                where sm.session_id = s.session_id
                  and sm.sender_user_id = #{userId}
                  and coalesce(sm.sent_by_shared_user, false) = false
            )
          )
    )
  )
